import React from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";

const Cart = () => {
  return (
    <div>
      <Navbar />
      <main className="page-wrapper">
        <h2>Your Cart</h2>
        <p>View items you've added to your cart and proceed to checkout.</p>
      </main>
      <Footer />
    </div>
  );
};

export default Cart;
